function blockTable(title, block, baseN) {
  const n = rowCount(block, baseN);
  let r = '';
  if (block === 'adeies') {
    for (let k = 0; k < n; k++) r += adeiaRow(k);
  } else {
    for (let k = 0; k < n; k++) {
      r += '<div class="opsx-line">' +
        '<span class="ox-i">' + (k + 1) + '</span>' +
        '<div style="flex:1">' + personSelect(block, k) + '</div></div>';
    }
  }
  // Ρεπό can be long — pack names into two columns so the card stays short.
  const twoCol = (block === 'repo');
  return '<div class="opsx-blk' + (twoCol ? ' ox-repo' : '') + '">' +
    '<h4>' + title +
    (block === 'adeies' ? ' <span>(διάρκεια)</span>' : '') +
    '</h4>' +
    (twoCol ? '<div class="opsx-lines">' + r + '</div>' : r) +
    '<button class="opsx-add" onclick="opsAddDailyRow(\'' + block + '\')">+ γραμμή</button>' +
    '</div>';
}
